function safeTwitchLogin(value, env, core){
  let raw = value;
  if(raw && typeof raw === "object"){
    raw = raw.login || raw.channel || raw.name || raw.twitchChannel || "";
  }
  raw = String(raw || core?.twitchChannel || env?.TWITCH_CHANNEL || "djfolsoe").trim().toLowerCase();
  if(raw === "[object object]" || raw === "undefined" || raw === "null" || !raw) raw = "djfolsoe";
  raw = raw.replace(/^@/,"").replace(/^https?:\/\/(www\.)?twitch\.tv\//,"").replace(/[^a-z0-9_]/g,"");
  return raw || "djfolsoe";
}

function cors() {
  return {
    "access-control-allow-origin":"*",
    "access-control-allow-methods":"GET,POST,OPTIONS",
    "access-control-allow-headers":"content-type,x-admin-token,authorization",
    "cache-control":"no-store"
  };
}

/* V817 GLOBAL EDITION - English-only API text sanitizer */
function englishOnlyText(s){
  return String(s||"")
    .replace(/NÆSTE SHOW/gi,"NEXT SHOW")
    .replace(/HVEM ER DJ FOLSOE\?/gi,"WHO IS DJ FOLSOE?")
    .replace(/MUSIKØNSKER/gi,"REQUESTS")
    .replace(/SENESTE FØLGER/gi,"LATEST FOLLOWER")
    .replace(/LATEST SUB/gi,"LATEST SUBSCRIBER")
    .replace(/LATEST RAID/gi,"LATEST RAID")
    .replace(/LATEST BITS/gi,"LATEST CHEER")
    .replace(/KLASSIKERE DER ALDRIG DØR/gi,"CLASSICS THAT NEVER DIE")
    .replace(/KAFFE, MUSIK OG GOD STEMNING/gi,"COFFEE, MUSIC AND GOOD VIBES")
    .replace(/BRUG !ØNSKE \/ !REQUEST \/ !WUNSCH I CHATTEN/gi,"USE !REQUEST IN CHAT");
}
function deepEnglishOnly(v){
  if(Array.isArray(v)) return v.map(deepEnglishOnly);
  if(v && typeof v === "object"){
    const out = {};
    for(const [k,val] of Object.entries(v)) out[k] = deepEnglishOnly(val);
    return out;
  }
  if(typeof v === "string") return englishOnlyText(v);
  return v;
}

function json(data,status=200) {
  return new Response(JSON.stringify(deepEnglishOnly(data),null,2), {status,headers:{"content-type":"application/json; charset=utf-8",...cors()}});
}
function adminOk(request, env) {
  const t = request.headers.get("x-admin-token") || (request.headers.get("authorization")||"").replace(/^Bearer\s+/i,"");
  return !!env.ADMIN_TOKEN && t === env.ADMIN_TOKEN;
}
