function cleanTickerText(v){
  if(v == null) return "";
  if(typeof v === "string" || typeof v === "number") return String(v);
  if(typeof v === "object"){
    return v.displayName || v.display_name || v.broadcaster_name || v.broadcaster_login || v.login || v.channel || v.userName || v.user_name || "";
  }
  return String(v);
}
function cleanChannelName(v){
  if(!v) return "djfolsoe";
  if(typeof v === "string") return v.replace(/^@/,"").trim() || "djfolsoe";
  if(typeof v === "object"){
    return String(v.broadcaster_login || v.login || v.channel || v.broadcaster_name || v.displayName || "djfolsoe").replace(/^@/,"").trim() || "djfolsoe";
  }
  return "djfolsoe";
}

