function seoPick(obj, lang, fallback=""){ if(!obj)return fallback; if(typeof obj==="string")return obj; return obj[lang]||obj.da||obj.en||fallback; }
function buildSeoPayload(core, lang="da"){
  const seo=core.seo||DEFAULT_CORE.seo||{};
  const domain=(seo.domain||"https://folsoetv.dk").replace(/\/$/,"");
  const title=seoPick(seo.title,lang,"DJ FOLSOE | Danish Twitch DJ");
  const description=seoPick(seo.description,lang,"Danish Twitch DJ and music streamer.");
  const image=seo.image||`${domain}/assets/og-dj-folsoe.jpg`;
  const sameAs=Array.isArray(seo.sameAs)?seo.sameAs:["https://twitch.tv/djfolsoe"];
  const shows=Array.isArray(seo.showPages)?seo.showPages:[];
  const schema={"@context":"https://schema.org","@graph":[
    {"@type":"Person","@id":`${domain}/#person`,"name":"DJ FOLSOE","alternateName":["DJ Folsoe","DJFOLSOE","Sune Folsø"],"url":domain,"image":image,"sameAs":sameAs,"jobTitle":"Twitch DJ and Music Streamer","nationality":"Denmark","knowsAbout":["Dance music","Trance","Eurodance","Retro Hits","Twitch streaming","DJ livestreams"]},
    {"@type":"WebSite","@id":`${domain}/#website`,"name":seo.siteName||"DJ FOLSOE TV","url":domain,"inLanguage":["da","en","de"],"description":description,"publisher":{"@id":`${domain}/#person`}},
    {"@type":"Organization","@id":`${domain}/#organization`,"name":"FOLSOE TV","url":domain,"sameAs":sameAs}
  ]};
  shows.forEach(show=>schema["@graph"].push({"@type":"BroadcastEvent","name":show.title,"description":show.description,"isAccessibleForFree":true,"url":`${domain}/${show.slug}`,"broadcastOfEvent":{"@type":"MusicEvent","name":show.title},"organizer":{"@id":`${domain}/#person`}}));
  return {ok:true,version:VERSION,lang,title,description,keywords:seo.keywords||[],image,domain,sameAs,showPages:shows,schema};
}
function sitemapXml(core){
  const seo=core.seo||DEFAULT_CORE.seo||{}; const domain=(seo.domain||"https://folsoetv.dk").replace(/\/$/,"");
  const shows=Array.isArray(seo.showPages)?seo.showPages:[]; const pages=["",...shows.map(s=>s.slug)];
  const now=new Date().toISOString().slice(0,10);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${pages.map(p=>`  <url><loc>${domain}/${p}</loc><lastmod>${now}</lastmod><changefreq>weekly</changefreq><priority>${p?"0.8":"1.0"}</priority></url>`).join("\n")}\n</urlset>`;
}
function robotsTxt(core){ const seo=core.seo||DEFAULT_CORE.seo||{}; const domain=(seo.domain||"https://folsoetv.dk").replace(/\/$/,""); return `User-agent: *\nAllow: /\nSitemap: ${domain}/sitemap.xml\n`; }


function detectRequestLanguage(text){
  const s=String(text||"").trim().toLowerCase();
  if(s.startsWith("!wunsch")) return "de";
  if(s.startsWith("!request")) return "en";
  return "da";
}
function cleanRequestSong(text){
  return String(text||"").trim().replace(/^!(ønske|onske|request|wunsch)\s*/i,"").trim();
}
function requestArtist(song){
  const s=String(song||"");
  if(s.includes(" - ")) return s.split(" - ")[0].trim();
  if(s.includes(" – ")) return s.split(" – ")[0].trim();
  return "";
}
async function getRequestList(env, core){
  try{
    if(env.DJF_DATA && env.DJF_DATA.get){
      const saved = await env.DJF_DATA.get("song-requests","json");
      if(Array.isArray(saved)) return saved;
    }
  }catch(e){}
  return Array.isArray(core.requests) ? core.requests : [];
}
async function putRequestList(env, list){
  if(env.DJF_DATA && env.DJF_DATA.put) await env.DJF_DATA.put("song-requests", JSON.stringify(list));
}
function requestStats(list){
  const approved = (Array.isArray(list)?list:[]).filter(x=>x && x.status !== "rejected");
  const todayKey = new Date().toISOString().slice(0,10);
  const today = approved.filter(x=>String(x.time||"").slice(0,10)===todayKey);
  const artists = {};
  const users = {};
  const langs = {};
  approved.forEach(x=>{
    const a=requestArtist(x.song||"");
    if(a) artists[a]=(artists[a]||0)+1;
    if(x.user) users[x.user]=(users[x.user]||0)+1;
    if(x.language) langs[x.language]=(langs[x.language]||0)+1;
  });
  const topArtist=Object.entries(artists).sort((a,b)=>b[1]-a[1])[0]||["-",0];
  const topRequester=Object.entries(users).sort((a,b)=>b[1]-a[1])[0]||["-",0];
  return {
    total:approved.length,
    today:today.length,
    topArtist:{name:topArtist[0],count:topArtist[1]},
    topRequester:{name:topRequester[0],count:topRequester[1]},
    languages:langs
  };
}
async function recentRequestsPayload(env, core){
  const list = await getRequestList(env, core);
  const approved = list.filter(x=>x && x.status !== "rejected");
  const pinned = approved.filter(x=>x.pinned);
  const normal = approved.filter(x=>!x.pinned);
  const visible = Number(core.requestSettings?.visible || 3);
  const items = [...pinned, ...normal].slice(0, visible);
  return {ok:true,items,all:list,stats:requestStats(list)};
}
async function addRequest(request, env, core){
  const body = await request.json().catch(()=>({}));
  const raw = String(body.text || body.song || body.request || "").trim();
  const user = String(body.user || body.username || body.displayName || "Twitch chat").trim();
  if(!raw) return json({ok:false,error:"Missing request text"},400);
  const language = body.language || detectRequestLanguage(raw);
  const song = cleanRequestSong(raw);
  const item = {
    id: body.id || ("req_"+Date.now()+"_"+Math.random().toString(36).slice(2,7)),
    user, song, language,
    show: body.show || core.activeTheme || "DJ FOLSOE LIVE",
    status: body.status || "approved",
    pinned: !!body.pinned,
    time: body.time || new Date().toISOString()
  };
  let list = await getRequestList(env, core);
  const keep = Number(core.requestSettings?.keep || 100);
  list = [item, ...(Array.isArray(list)?list:[])].slice(0, keep);
  await putRequestList(env, list);
  return json({ok:true,item,items:list.slice(0,Number(core.requestSettings?.visible||3)),stats:requestStats(list)});
}
async function updateRequests(request, env, core){
  if (!adminOk(request,env)) return json({error:"Unauthorized"},401);
  const body = await request.json().catch(()=>({}));
  const items = Array.isArray(body.items) ? body.items : [];
  await putRequestList(env, items);
  core.requests = items.slice(0, Number(core.requestSettings?.keep || 100));
  await putCore(env, core);
  return json({ok:true,items,stats:requestStats(items)});
}


async function enrichCommunityWall(env, core){
  const wall = (core.communityWall || DEFAULT_CORE.communityWall || [])
    .filter(x=>x && x.active !== false)
    .sort((a,b)=>(Number(b.pinned||0)-Number(a.pinned||0)) || (Number(a.priority||99)-Number(b.priority||99)));
  const enriched = [];
  for(const item of wall){
    const login = safeTwitchLogin(item.login || item.user || "", env, core);
    let tw = {};
    try{ if(login && login !== "djfolsoe") tw = await twitchProfile(env, {...core,twitchChannel:login}); }catch(e){}
    enriched.push({
      ...item,
      login,
      displayName:tw.displayName || item.user || item.name || login,
      avatar:tw.avatar || "",
      isLive:!!tw.isLive,
      twitchUrl: login ? "https://twitch.tv/"+login : ""
    });
  }
  return enriched;
}
function buildCommunityStats(core, requestStatsData){
  const base = core.communityStats || DEFAULT_CORE.communityStats || {};
  return {
    followers: Number(core.station?.followers || base.followers || 870),
    requests: Number(requestStatsData?.total || base.requests || 0),
    raids: Number(base.raids || 0),
    subs: Number(core.station?.subs || base.subs || 0),
    members: Number(base.members || 0)
  };
}

